def encode(message):
    vowels = 'aeiou'
    shifted_vowels = {v: chr((ord(v) - ord('a') + 2) % 26 + ord('a')) for v in vowels}
    shifted_vowels.update({v.upper(): chr((ord(v.upper()) - ord('A') + 2) % 26 + ord('A')) for v in vowels})

    result = []
    for char in message:
        if char.isalpha():
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
            if char.lower() in shifted_vowels:
                result[-1] = shifted_vowels[char.lower()]
        else:
            result.append(char)
    return ''.join(result)
